mapper.select:
SELECT 
	CHATROOM_NO
	, PRJ_NO
	, USER_ID
	, READ_MESSAGE_NO
FROM CHATROOM_MEM
WHERE CHATROOM_NO = #{chatroomNo}
AND PRJ_NO = #{prjNo}
AND USER_ID = #{userId}

mapper.insert:
INSERT INTO CHATROOM_MEM (
	CHATROOM_NO
	, PRJ_NO
	, USER_ID
	, READ_MESSAGE_NO
) VALUES (
	#{chatroomNo}
	, #{prjNo}
	, #{userId}
	, #{readMessageNo}
)

mapper.update:
UPDATE CHATROOM_MEM
SET 
	READ_MESSAGE_NO = #{readMessageNo}
WHERE CHATROOM_NO = #{chatroomNo}
AND PRJ_NO = #{prjNo}
AND USER_ID = #{userId}

mapper.delete:
DELETE FROM CHATROOM_MEM
WHERE CHATROOM_NO = #{chatroomNo}
AND PRJ_NO = #{prjNo}
AND USER_ID = #{userId}
